AS r("lessonId" text,"sourcePage" int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE verified integer; inserted integer;
BEGIN
 IF (SELECT count(*) FROM pg_temp.bh_g1_learning_journals_25)<>25
 OR (SELECT count(DISTINCT lesson_id) FROM pg_temp.bh_g1_learning_journals_25)<>5
 OR (SELECT count(DISTINCT (lesson_id,activity_order)) FROM pg_temp.bh_g1_learning_journals_25)<>25
 OR EXISTS (SELECT 1 FROM pg_temp.bh_g1_learning_journals_25
  WHERE length(content->>'originalReference')<180 OR length(prompt)<12
   OR content ? 'correct' OR content ? 'answer' OR answer IS NULL)
 THEN RAISE EXCEPTION 'Malformed journal lesson-specific templates'; END IF;
 WITH targets AS (
 SELECT l.id,l.title,l.source_page_start,co.code country,g.grade_number grade,
 (SELECT COUNT(*) FROM public.lesson_activities a WHERE a.lesson_id=l.id AND a.is_published) n,
 (SELECT MAX(a.activity_order) FROM public.lesson_activities a WHERE a.lesson_id=l.id) max_position,
 EXISTS (SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id) has_history,
 EXISTS (SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id) has_activity_history,
 EXISTS (SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id) has_question_history
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
 JOIN public.grades g ON g.id=u.grade_id JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 WHERE l.status='published' AND l.title='مفكرة التعلم' AND g.grade_number=1 AND co.code='BH'
 )
 SELECT COUNT(DISTINCT t.id) INTO verified FROM targets t
 JOIN pg_temp.bh_g1_learning_journals_25 src ON src.lesson_id=t.id AND src.source_page=t.source_page_start
 WHERE t.n=1 AND t.max_position=1
 AND NOT t.has_history AND NOT t.has_activity_history AND NOT t.has_question_history;
 IF verified<>5 THEN RAISE EXCEPTION 'Grade1 Bahrain five journals changed or have learner history: %',verified; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_BH_G1_5_LEARNING_JOURNALS_25_ORIGINAL_20261030')
 THEN RAISE EXCEPTION 'Batch already inserted, abort'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'استعن ببطاقة الإثراء الأصلية في مفكرتك، ثم أجب. النص ليس من ورقة الوزارة.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN public.curricula cu ON cu.id=g.curriculum_id JOIN public.countries co ON co.id=cu.country_id
 JOIN pg_temp.bh_g1_learning_journals_25 t ON t.lesson_id=l.id AND t.source_page=l.source_page_start
 WHERE l.status='published' AND l.title='مفكرة التعلم' AND g.grade_number=1 AND co.code='BH'
 AND NOT EXISTS (SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 AND NOT EXISTS (SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 AND NOT EXISTS (SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>25 THEN RAISE EXCEPTION 'Atomic rollback: expected 25 new formative activities, got %',inserted; END IF;
 RAISE NOTICE 'DADYOOM_BH_G1_5_LEARNING_JOURNALS_25_ORIGINAL_20261030=%',inserted;
END $safe$;
COMMIT;